function solve(items) {
  // A set remembers what we've kept; one pass keeps the first of each, in order.
  if (items == null || items.length === 0) return [];
  const seen = new Set();
  const result = [];
  for (const item of items) {
    if (!seen.has(item)) {
      seen.add(item);
      result.push(item);
    }
  }
  return result;
}

